const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={view:"dashboard",brand:"all",records:[],dashboard:null,businesses:[],search:"",status:"all",archived:false,current:null,portalLinks:{}};
const labels={all:"All businesses",wbm:"Weddings By Mark",ivory:"Ivory Digital"};
const titles={dashboard:"Good morning, Mark",weddings:"Wedding bookings",projects:"Ivory Digital projects",calendar:"Calendar",workflows:"Workflows",invoices:"Invoices",documents:"Documents",packages:"Packages & pricing",communications:"Templates & email",settings:"Settings"};
const subtitles={dashboard:"Here's what needs your attention today.",weddings:"Every couple, detail and deadline in one place.",projects:"Website clients, services and project milestones.",calendar:"Wedding dates and project deadlines at a glance.",workflows:"Add, edit, complete or remove every task.",invoices:"Bank-transfer invoices in one chronological sequence.",documents:"Contracts, forms, questionnaires and attachments.",packages:"Wedding packages, deposits, add-ons and package eligibility.",communications:"Email wording, agreements, secure links and reminders.",settings:"Separate branding and invoice details for both businesses."};
const statuses=["enquiry","quoted","confirmed","in_progress","completed","cancelled"];

function esc(v=""){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function attr(v=""){return esc(v)}
function fmtDate(v){if(!v)return "No date set";return new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",year:"numeric"}).format(new Date(v.slice(0,10)+"T12:00:00"))}
function fmtDateTime(v){if(!v)return "No date";return new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(v))}
function money(v){return new Intl.NumberFormat("en-GB",{style:"currency",currency:"GBP",minimumFractionDigits:2}).format(Number(v||0))}
function bytes(v){return Number(v||0)<1048576?`${Math.max(1,Math.round(Number(v||0)/1024))} KB`:`${(Number(v)/1048576).toFixed(1)} MB`}
function initials(r){return (r.title||"?").split(/\s+|&/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function statusText(s){return String(s||"").replaceAll("_"," ")}
function statusClass(s){return /due|quoted|enquiry|unpaid|part_paid/.test(s)?"warning":/cancelled/.test(s)?"danger":/paid|completed|confirmed/.test(s)?"success":""}
function value(id){return $(id)?.value??""}
function nullable(v){const x=String(v??"").trim();return x||null}
async function api(path,options={}){const res=await fetch(path,{credentials:"same-origin",headers:{...(options.body instanceof FormData?{}:{"Content-Type":"application/json"}),...(options.headers||{})},...options});if(res.status===401){showLogin();throw new Error("Please sign in")};if(res.status===204)return null;const data=await res.json().catch(()=>({}));if(!res.ok){const detail=Array.isArray(data.detail)?data.detail.map(x=>x.msg).join(", "):data.detail;throw new Error(detail||"Something went wrong")}return data}
function toast(text,type=""){const el=$("#toast");el.textContent=text;el.className=`toast ${type}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add("hidden"),3000)}
function showLogin(){$("#app").classList.add("hidden");$("#login").classList.remove("hidden")}
function showApp(){$("#login").classList.add("hidden");$("#app").classList.remove("hidden")}

async function init(){bind();try{const me=await api("/api/auth/me");$("#login-email").value=me.email;showApp();await loadAll()}catch(e){showLogin()}}
function bind(){
  $("#login-form").onsubmit=async e=>{e.preventDefault();$("#login-error").textContent="";try{await api("/api/auth/login",{method:"POST",body:JSON.stringify({email:value("#login-email"),password:value("#login-password")})});showApp();await loadAll()}catch(err){$("#login-error").textContent=err.message}};
  $("#logout").onclick=async()=>{await api("/api/auth/logout",{method:"POST"});showLogin()};
  $("#brand-toggle").onclick=()=>$("#brand-menu").classList.toggle("hidden");
  $$("#brand-menu button").forEach(b=>b.onclick=()=>{state.brand=b.dataset.brand;$("#brand-label").textContent=labels[state.brand];$("#brand-dot").className=`dot ${state.brand}`;$("#brand-menu").classList.add("hidden");render()});
  $$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
  $("#open-menu").onclick=$("#mobile-more").onclick=()=>toggleMenu(true);$("#close-menu").onclick=$("#scrim").onclick=()=>toggleMenu(false);
  $("#add-record").onclick=$("#mobile-add").onclick=()=>openRecordModal();
  $("#modal-overlay").onclick=closeModal;$("#drawer-overlay").onclick=closeDrawer;
  $("#search").oninput=e=>{state.search=e.target.value.toLowerCase();render()};
  document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeModal();closeDrawer();toggleMenu(false)}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();$("#search").focus()}});
}
function toggleMenu(on){$("#sidebar").classList.toggle("open",on);$("#scrim").classList.toggle("hidden",!on)}
async function navigate(view){state.view=view;state.status="all";toggleMenu(false);if(state.archived&&!['weddings','projects'].includes(view)){state.archived=false;await refresh()}$$('[data-view]').forEach(b=>b.classList.toggle("active",b.dataset.view===view));render()}
async function loadAll(){const [dash,records,businesses]=await Promise.all([api("/api/dashboard"),api("/api/bookings"),api("/api/businesses")]);state.dashboard=dash;state.records=records;state.businesses=businesses;render()}
async function refresh(){const [dash,records]=await Promise.all([api("/api/dashboard"),api(`/api/bookings?archived=${state.archived}`)]);state.dashboard=dash;state.records=records}
function filtered(items=state.records){return items.filter(r=>(state.brand==="all"||r.brand===state.brand)&&(!state.search||`${r.title} ${r.venue_or_project||""} ${r.package_name||""} ${r.client?.email||""}`.toLowerCase().includes(state.search))&&(state.status==="all"||r.status===state.status))}

function render(){
  $("#page-eyebrow").textContent=labels[state.brand].toUpperCase();$("#page-title").textContent=titles[state.view];$("#page-subtitle").textContent=subtitles[state.view];
  const digital=state.view==="projects"||state.brand==="ivory";$("#add-record").innerHTML=`<span>＋</span> Add ${digital?"project":"booking"}`;
  if(state.view==="dashboard")renderDashboard();else if(["weddings","projects"].includes(state.view))renderRecords();else if(state.view==="calendar")renderCalendar();else if(state.view==="workflows")renderWorkflows();else if(state.view==="invoices")renderInvoices();else if(state.view==="documents")renderDocuments();else if(state.view==="packages")renderPackages();else if(state.view==="communications")renderCommunications();else renderSettings();
}
function recordRow(r){return `<button class="record-row" data-record="${r.id}"><span class="record-avatar ${r.brand}">${esc(initials(r))}</span><span class="record-main"><strong>${esc(r.title)}</strong><small>${esc(r.venue_or_project||r.client.email)}</small></span><span class="record-date">${esc(fmtDate(r.event_date))}</span><span class="status ${statusClass(r.status)}">${esc(statusText(r.status))}</span><span class="more">•••</span></button>`}
function taskRow(t,compact=false){return `<div class="task-row ${t.completed?"done":""}" data-task="${t.id}"><button class="task-toggle" data-action="toggle-task" aria-label="Toggle task">${t.completed?"✓":""}</button><button class="task-main" data-record="${t.booking_id}"><strong>${esc(t.title)}</strong><small>${esc(t.booking_title||"")}</small></button><time>${t.due_at?esc(fmtDate(t.due_at)):"No date"}</time>${compact?"":`<button class="mini" data-action="edit-task">Edit</button><button class="mini danger-text" data-action="delete-task">Delete</button>`}</div>`}
function wireRecords(root=$("#content")){$$('[data-record]',root).forEach(b=>b.onclick=e=>{if(e.target.closest('[data-action]'))return;openDrawer(b.dataset.record)});$$('[data-jump]',root).forEach(b=>b.onclick=()=>navigate(b.dataset.jump))}

function renderDashboard(){const d=state.dashboard||{};const upcoming=filtered(d.upcoming||[]);const tasks=(d.tasks||[]).filter(t=>state.brand==="all"||state.records.find(r=>r.id===t.booking_id)?.brand===state.brand);$("#content").innerHTML=`
  <section class="stats">
    <button class="stat-card" data-jump="${state.brand==="ivory"?"projects":"weddings"}"><i class="metric teal">□</i><span><strong>${state.brand==="ivory"?filtered().length:d.confirmed||0}</strong><small>${state.brand==="ivory"?"Active projects":"Confirmed weddings"}</small></span><em>Open records</em></button>
    <button class="stat-card" data-jump="weddings"><i class="metric blue">♙</i><span><strong>${d.open_enquiries||0}</strong><small>Open enquiries</small></span><em>Ready to follow up</em></button>
    <button class="stat-card" data-jump="invoices"><i class="metric amber">£</i><span><strong>${money(d.outstanding)}</strong><small>Outstanding</small></span><em>View invoices</em></button>
  </section>
  <section class="dash-grid"><article class="panel"><div class="panel-title"><div><h2>${state.brand==="ivory"?"Active projects":"Upcoming dates"}</h2><p>Your next bookings and deadlines</p></div><button data-jump="calendar">View all</button></div>${upcoming.length?upcoming.slice(0,7).map(recordRow).join(""):`<div class="empty"><strong>No upcoming records</strong>Add a booking or project to get started.</div>`}</article>
  <article class="panel"><div class="panel-title"><div><h2>Open tasks · ${d.open_tasks||0}</h2><p>Tap the circle to complete</p></div><button data-jump="workflows">View all</button></div>${tasks.length?tasks.slice(0,7).map(t=>taskRow(t,true)).join(""):`<div class="empty"><strong>You're all caught up</strong>No open tasks.</div>`}</article></section>`;
  wireRecords();$$('[data-action="toggle-task"]',$("#content")).forEach(b=>b.onclick=()=>toggleTask(b.closest("[data-task]")));
}

function renderRecords(){const kind=state.view==="projects"?"digital":"wedding";const rows=filtered().filter(r=>r.kind===kind);$("#content").innerHTML=`<article class="panel"><div class="tools"><div class="filter-pills">${["all",...statuses].map(s=>`<button data-status="${s}" class="${state.status===s?"active":""}">${s==="all"?"All":statusText(s)}</button>`).join("")}</div><label class="archive-switch"><input id="archive-toggle" type="checkbox" ${state.archived?"checked":""}> Archived</label></div><div class="table-wrap"><div class="table"><div class="table-head"><span>Client</span><span>Venue / project</span><span>Date</span><span>Status</span><span>Value</span></div>${rows.map(r=>`<button class="table-row" data-record="${r.id}"><span class="client-cell"><i class="client-avatar ${r.brand}">${esc(initials(r))}</i><strong>${esc(r.title)}</strong></span><span>${esc(r.venue_or_project||"Not set")}</span><span>${esc(fmtDate(r.event_date))}</span><span class="status ${statusClass(r.status)}">${esc(statusText(r.status))}</span><strong>${money(r.quoted_total)}</strong></button>`).join("")}</div>${rows.length?"":`<div class="empty"><strong>No ${state.archived?"archived ":""}records found</strong>${state.archived?"Nothing has been archived here.":"Use Add to create the first one."}</div>`}</div></article>`;
  $$('[data-status]').forEach(b=>b.onclick=()=>{state.status=b.dataset.status;renderRecords()});$("#archive-toggle").onchange=async e=>{state.archived=e.target.checked;await refresh();renderRecords()};wireRecords();
}

function renderCalendar(){const rows=filtered().filter(r=>r.event_date).sort((a,b)=>a.event_date.localeCompare(b.event_date));const groups={};rows.forEach(r=>{const key=new Intl.DateTimeFormat("en-GB",{month:"long",year:"numeric"}).format(new Date(r.event_date+"T12:00:00"));(groups[key]??=[]).push(r)});$("#content").innerHTML=Object.keys(groups).length?`<div class="calendar-list">${Object.entries(groups).map(([month,items])=>`<section class="panel month"><div class="panel-title"><div><h2>${esc(month)}</h2><p>${items.length} dated record${items.length===1?"":"s"}</p></div></div>${items.map(r=>`<button class="calendar-row" data-record="${r.id}"><time><strong>${r.event_date.slice(8,10)}</strong><small>${new Intl.DateTimeFormat("en-GB",{weekday:"short"}).format(new Date(r.event_date+"T12:00:00"))}</small></time><span><strong>${esc(r.title)}</strong><small>${esc(r.venue_or_project||r.package_name||"")}</small></span><i class="brand-badge ${r.brand}">${esc(labels[r.brand])}</i></button>`).join("")}</section>`).join("")}</div>`:`<div class="panel empty"><strong>No dated records</strong>Add a date to a booking or project and it will appear here.</div>`;wireRecords()}

async function renderWorkflows(){const token=state.view;$("#content").innerHTML=`<div class="panel loading">Loading workflows…</div>`;try{const qs=state.brand==="all"?"":`?brand=${state.brand}`;const tasks=await api(`/api/tasks${qs}`);if(state.view!==token)return;const visible=tasks.filter(t=>!state.search||`${t.title} ${t.booking_title}`.toLowerCase().includes(state.search));$("#content").innerHTML=`<article class="panel"><div class="panel-title"><div><h2>All workflow tasks</h2><p>${visible.filter(t=>!t.completed).length} open · ${visible.filter(t=>t.completed).length} complete</p></div></div><div class="task-list">${visible.map(t=>taskRow(t)).join("")||`<div class="empty"><strong>No tasks found</strong>Tasks are created automatically with new records.</div>`}</div></article>`;wireTaskActions($("#content"))}catch(e){showError(e)}}
function wireTaskActions(root){$$('[data-action="toggle-task"]',root).forEach(b=>b.onclick=()=>toggleTask(b.closest("[data-task]")));$$('[data-action="edit-task"]',root).forEach(b=>b.onclick=()=>editTask(b.closest("[data-task]").dataset.task));$$('[data-action="delete-task"]',root).forEach(b=>b.onclick=()=>deleteTask(b.closest("[data-task]").dataset.task));$$('[data-record]',root).forEach(b=>b.onclick=()=>openDrawer(b.dataset.record))}
async function toggleTask(row){try{const done=!row.classList.contains("done");await api(`/api/tasks/${row.dataset.task}`,{method:"PATCH",body:JSON.stringify({completed:done})});await refresh();toast(done?"Task completed":"Task reopened");state.current?await openDrawer(state.current.id,state.currentTab||"Workflow"):render()}catch(e){toast(e.message,"error")}}
async function editTask(id){const tasks=await api("/api/tasks");const t=tasks.find(x=>x.id===id);if(!t)return;showModal("Edit task",`<label class="full">Task<input id="task-title" value="${attr(t.title)}" required></label><label class="full">Due date and time<input id="task-due" type="datetime-local" value="${t.due_at?attr(t.due_at.slice(0,16)):""}"></label>`,async()=>{await api(`/api/tasks/${id}`,{method:"PATCH",body:JSON.stringify({title:value("#task-title").trim(),due_at:nullable(value("#task-due"))})});closeModal();await refresh();toast("Task updated");state.current?openDrawer(state.current.id,"Workflow"):render()})}
async function deleteTask(id){if(!confirm("Delete this task?"))return;try{await api(`/api/tasks/${id}`,{method:"DELETE"});await refresh();toast("Task deleted");state.current?openDrawer(state.current.id,"Workflow"):render()}catch(e){toast(e.message,"error")}}

async function renderInvoices(){const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading invoices…</div>`;try{const qs=state.brand==="all"?"":`?brand=${state.brand}`;let rows=await api(`/api/invoices${qs}`);rows=rows.filter(i=>!state.search||`${i.number} ${i.client}`.toLowerCase().includes(state.search));if(state.view!==view)return;$("#content").innerHTML=`<article class="panel"><div class="panel-title"><div><h2>Invoice register</h2><p>${rows.length} invoice${rows.length===1?"":"s"} · shared WBM / ID sequence</p></div></div><div class="table-wrap"><div class="table invoices"><div class="table-head"><span>Invoice</span><span>Client</span><span>Brand</span><span>Issued</span><span>Balance</span><span>Status</span><span>Files</span></div>${rows.map(i=>`<div class="table-row"><strong>${esc(i.number)}</strong><button class="link-button" data-record="${i.booking_id}">${esc(i.client||"")}</button><span class="brand-badge ${i.brand}">${esc(labels[i.brand])}</span><span>${esc(fmtDate(i.issue_date))}</span><strong>${money(i.balance)}</strong><span class="status ${statusClass(i.status)}">${esc(statusText(i.status))}</span><span class="file-actions"><a href="/api/invoices/${i.id}/pdf" title="Download invoice">PDF</a>${i.paid>0?`<a href="/api/invoices/${i.id}/receipt.pdf" title="Download receipt">Receipt</a>`:""}</span></div>`).join("")}</div>${rows.length?"":`<div class="empty"><strong>No invoices yet</strong>Create one from a record's Finance tab.</div>`}</div></article>`;wireRecords()}catch(e){showError(e)}}

async function renderDocuments(){const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading documents…</div>`;try{const qs=state.brand==="all"?"":`?brand=${state.brand}`;let rows=await api(`/api/documents${qs}`);rows=rows.filter(d=>!state.search||`${d.original_name} ${d.booking_title} ${d.category}`.toLowerCase().includes(state.search));if(state.view!==view)return;$("#content").innerHTML=`<article class="panel"><div class="panel-title"><div><h2>Document library</h2><p>Everything remains attached to its correct record</p></div></div><div class="document-list">${rows.map(d=>documentRow(d,true)).join("")||`<div class="empty"><strong>No documents uploaded</strong>Open a record to upload contracts, forms or images.</div>`}</div></article>`;wireDocumentActions($("#content"))}catch(e){showError(e)}}
function documentRow(d,showRecord=false){return `<div class="document-row" data-document="${d.id}"><i>▤</i><span><strong>${esc(d.original_name)}</strong><small>${esc(statusText(d.category))} · ${bytes(d.size_bytes)}${showRecord?` · ${esc(d.booking_title)}`:""}</small></span>${showRecord?`<button class="link-button" data-record="${d.booking_id}">Open record</button>`:""}<a class="secondary small-button" href="/api/documents/${d.id}">Download</a><button class="mini danger-text" data-action="delete-document">Delete</button></div>`}
function wireDocumentActions(root){$$('[data-action="delete-document"]',root).forEach(b=>b.onclick=()=>deleteDocument(b.closest("[data-document]").dataset.document));$$('[data-record]',root).forEach(b=>b.onclick=()=>openDrawer(b.dataset.record))}
async function deleteDocument(id){if(!confirm("Delete this document from the booking system?"))return;try{await api(`/api/documents/${id}`,{method:"DELETE"});toast("Document deleted");state.current?openDrawer(state.current.id,"Documents"):renderDocuments()}catch(e){toast(e.message,"error")}}

async function renderPackages(){
  const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading packages…</div>`;
  try{
    const d=await api("/api/catalog?brand=wbm&include_inactive=true");if(state.view!==view)return;
    const packageNames=Object.fromEntries(d.packages.map(x=>[x.code,x.name.replace(/ Package.*$/,"")]));
    $("#content").innerHTML=`<section class="comm-status"><div class="ready"><strong>Website enquiry form ready</strong><span>Every submission automatically creates a new wedding enquiry here.</span></div><a class="secondary embed-preview" href="/enquiry" target="_blank" rel="noopener">Preview form</a><button id="copy-enquiry-embed" class="secondary">Copy website embed code</button></section><div class="catalog-columns"><section class="panel"><div class="panel-title"><div><h2>Wedding packages</h2><p>These appear in price order in the couple's private quote</p></div><button id="new-package" class="primary">＋ Add package</button></div><div class="catalog-list">${d.packages.map(p=>`<article class="catalog-card ${p.is_active?"":"inactive"}"><header><div><strong>${esc(p.name)}</strong><span class="status ${p.is_active?"success":""}">${p.is_active?"Active":"Hidden"}</span></div><button class="mini" data-package="${p.id}">Edit</button></header><p>${esc(p.description)}</p><div class="catalog-meta"><span>Deposit ${money(p.deposit_amount)} · position ${p.display_order}</span><strong class="catalog-price">${money(p.price)}</strong></div></article>`).join("")}</div></section><section class="panel"><div class="panel-title"><div><h2>Add-ons</h2><p>Eligibility controls which package shows each extra</p></div><button id="new-addon" class="primary">＋ Add extra</button></div><div class="catalog-list">${d.addons.map(a=>`<article class="catalog-card ${a.is_active?"":"inactive"}"><header><div><strong>${esc(a.name)}</strong><span class="status ${a.is_active?"success":""}">${a.is_active?"Active":"Hidden"}</span></div><button class="mini" data-addon="${a.id}">Edit</button></header><p>${esc(a.description)}</p><div class="catalog-meta"><div class="catalog-eligibility">${a.eligible_package_codes.map(code=>`<i>${esc(packageNames[code]||code)}</i>`).join("")||"All packages"}</div><strong class="catalog-price">${money(a.price)}</strong></div></article>`).join("")}</div></section></div>`;
    $$('[data-package]').forEach(b=>b.onclick=()=>editPackage(d.packages.find(x=>x.id===b.dataset.package)));
    $$('[data-addon]').forEach(b=>b.onclick=()=>editAddon(d.addons.find(x=>x.id===b.dataset.addon),d.packages));
    $("#new-package").onclick=()=>newPackage(d.packages);
    $("#new-addon").onclick=()=>newAddon(d.packages,d.addons);
    $("#copy-enquiry-embed").onclick=async()=>{const origin=location.origin;const code=`<iframe id="wbm-enquiry-form" src="${origin}/enquiry" style="width:100%;max-width:1040px;height:1600px;border:0" loading="lazy" title="Weddings By Mark enquiry form"></iframe>\n<script data-iframe-id="wbm-enquiry-form" src="${origin}/static/enquiry-embed.js"></script>`;await navigator.clipboard.writeText(code);toast("Website embed code copied")};
  }catch(e){showError(e)}
}
function editPackage(p){showModal(`Edit ${p.name}`,`<label class="full">Package name<input id="catalog-name" value="${attr(p.name)}" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" value="${p.price}" required></label><label>Booking fee / deposit<input id="catalog-deposit" type="number" min="0" step="0.01" value="${p.deposit_amount}" required></label><label>Display position<input id="catalog-order" type="number" min="0" value="${p.display_order}" required></label><label>Visibility<select id="catalog-active"><option value="true" ${p.is_active?"selected":""}>Active</option><option value="false" ${p.is_active?"":"selected"}>Hidden</option></select></label><label class="full">Full package wording<textarea id="catalog-description" rows="15" required>${esc(p.description)}</textarea></label>`,async()=>{await api(`/api/catalog/packages/${p.id}`,{method:"PATCH",body:JSON.stringify({name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),deposit_amount:Number(value("#catalog-deposit")),display_order:Number(value("#catalog-order")),is_active:value("#catalog-active")==="true",description:value("#catalog-description").trim()})});closeModal();toast("Package saved");renderPackages()},"Changes appear on future client quotes. Accepted quotes keep their original wording and price.")}
function editAddon(a,packages){const checks=packages.map(p=>`<label class="check-option"><input type="checkbox" name="eligible" value="${p.code}" ${a.eligible_package_codes.includes(p.code)?"checked":""}><span>${esc(p.name)}</span></label>`).join("");showModal(`Edit ${a.name}`,`<label class="full">Add-on name<input id="catalog-name" value="${attr(a.name)}" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" value="${a.price}" required></label><label>Display position<input id="catalog-order" type="number" min="0" value="${a.display_order}" required></label><label>Visibility<select id="catalog-active"><option value="true" ${a.is_active?"selected":""}>Active</option><option value="false" ${a.is_active?"":"selected"}>Hidden</option></select></label><label class="full">Description<textarea id="catalog-description" rows="5" required>${esc(a.description)}</textarea></label><div class="full"><div class="section-label">AVAILABLE WITH</div><div class="check-grid">${checks}</div></div>`,async()=>{await api(`/api/catalog/addons/${a.id}`,{method:"PATCH",body:JSON.stringify({name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),display_order:Number(value("#catalog-order")),is_active:value("#catalog-active")==="true",description:value("#catalog-description").trim(),eligible_package_codes:$$('input[name="eligible"]:checked',$("#modal")).map(x=>x.value)})});closeModal();toast("Add-on saved");renderPackages()},"Choose the exact packages that are allowed to use this extra.")}
function newPackage(packages){showModal("Add wedding package",`<label>Internal code<input id="catalog-code" pattern="[a-z0-9_-]+" placeholder="diamond" required></label><label>Display position<input id="catalog-order" type="number" min="0" value="${packages.length+1}" required></label><label class="full">Package name<input id="catalog-name" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" required></label><label>Booking fee / deposit<input id="catalog-deposit" type="number" min="0" step="0.01" required></label><label class="full">Full package wording<textarea id="catalog-description" rows="12" required></textarea></label>`,async()=>{await api("/api/catalog/packages?brand=wbm",{method:"POST",body:JSON.stringify({code:value("#catalog-code").trim().toLowerCase(),name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),deposit_amount:Number(value("#catalog-deposit")),display_order:Number(value("#catalog-order")),description:value("#catalog-description").trim(),is_active:true})});closeModal();toast("Package added");renderPackages()})}
function newAddon(packages,addons){const checks=packages.map(p=>`<label class="check-option"><input type="checkbox" name="eligible" value="${p.code}"><span>${esc(p.name)}</span></label>`).join("");showModal("Add optional extra",`<label>Internal code<input id="catalog-code" pattern="[a-z0-9_-]+" required></label><label>Display position<input id="catalog-order" type="number" min="0" value="${addons.length+1}" required></label><label class="full">Add-on name<input id="catalog-name" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" required></label><label class="full">Description<textarea id="catalog-description" rows="5" required></textarea></label><div class="full"><div class="section-label">AVAILABLE WITH</div><div class="check-grid">${checks}</div></div>`,async()=>{await api("/api/catalog/addons?brand=wbm",{method:"POST",body:JSON.stringify({code:value("#catalog-code").trim().toLowerCase(),name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),display_order:Number(value("#catalog-order")),description:value("#catalog-description").trim(),eligible_package_codes:$$('input[name="eligible"]:checked',$("#modal")).map(x=>x.value),is_active:true})});closeModal();toast("Add-on added");renderPackages()})}

async function renderCommunications(){const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading templates…</div>`;try{const qs=state.brand==="all"?"":`?brand=${state.brand}`;const d=await api(`/api/communications/templates${qs}`);if(state.view!==view)return;$("#content").innerHTML=`<section class="comm-status"><div class="${d.smtp_configured?"ready":"warning-box"}"><strong>SMTP ${d.smtp_configured?"ready":"not configured"}</strong><span>${d.smtp_configured?"Emails can be sent from each record.":"Add SMTP_USERNAME and SMTP_PASSWORD to the Dockge YAML."}</span></div><div class="${d.reminders_enabled?"ready":"warning-box"}"><strong>Automatic reminders ${d.reminders_enabled?"enabled":"paused"}</strong><span>${d.reminders_enabled?"The system scans automatically.":"Set REMINDERS_ENABLED=true when you are ready."}</span></div><button id="run-reminders" class="secondary" ${d.smtp_configured?"":"disabled"}>Run reminder check now</button></section><div class="comm-grid"><section class="panel"><div class="panel-title"><div><h2>Email templates</h2><p>Use {client_first_name}, {portal_url}, {event_date} and other booking fields</p></div></div><div class="template-list">${d.templates.map(t=>`<button class="template-row" data-template="${t.id}"><i class="brand-badge ${t.brand}">${t.brand==="wbm"?"WBM":"ID"}</i><span><strong>${esc(t.display_name)}</strong><small>${esc(t.subject)}</small></span><b>Edit</b></button>`).join("")}</div></section><section class="panel"><div class="panel-title"><div><h2>Agreement templates</h2><p>The exact accepted wording is permanently snapshotted</p></div></div><div class="template-list">${d.contracts.filter(c=>state.brand==="all"||c.brand===state.brand).map(c=>`<button class="template-row" data-contract="${c.id}"><i class="brand-badge ${c.brand}">${c.brand==="wbm"?"WBM":"ID"}</i><span><strong>${esc(c.title)}</strong><small>${esc(c.version)}</small></span><b>Edit</b></button>`).join("")}</div></section></div>`;$$('[data-template]').forEach(b=>b.onclick=()=>editEmailTemplate(d.templates.find(x=>x.id===b.dataset.template)));$$('[data-contract]').forEach(b=>b.onclick=()=>editContractTemplate(d.contracts.find(x=>x.id===b.dataset.contract)));$("#run-reminders").onclick=async()=>{try{const result=await api("/api/communications/reminders/run",{method:"POST"});toast(`Reminder check: ${result.sent} sent, ${result.failed} failed`)}catch(e){toast(e.message,"error")}}}catch(e){showError(e)}}
function editEmailTemplate(t){showModal(`Edit ${t.display_name}`,`<label class="full">Template name<input id="template-name" value="${attr(t.display_name)}" required></label><label class="full">Subject<input id="template-subject" value="${attr(t.subject)}" required></label><label class="full">Email body<textarea id="template-body" rows="14" required>${esc(t.body)}</textarea></label>`,async()=>{await api(`/api/communications/templates/${t.id}`,{method:"PATCH",body:JSON.stringify({display_name:value("#template-name").trim(),subject:value("#template-subject").trim(),body:value("#template-body").trim()})});closeModal();toast("Email template saved");renderCommunications()},"Changes apply to future emails only.")}
function editContractTemplate(c){showModal(`Edit ${c.title}`,`<label>Agreement title<input id="contract-title" value="${attr(c.title)}" required></label><label>Version<input id="contract-version" value="${attr(c.version)}" required></label><label class="full">Complete agreement wording<textarea id="contract-body" rows="18" required>${esc(c.body)}</textarea></label>`,async()=>{await api(`/api/communications/contracts/${c.id}`,{method:"PATCH",body:JSON.stringify({title:value("#contract-title").trim(),version:value("#contract-version").trim(),body:value("#contract-body").trim()})});closeModal();toast("Agreement template saved");renderCommunications()},"Already accepted agreements keep their original wording.")}

function renderSettings(){const rows=state.businesses.filter(b=>state.brand==="all"||b.brand===state.brand);$("#content").innerHTML=`<div class="settings-grid">${rows.map(b=>{const bank=b.bank_details||{};return `<form class="panel business-form" data-business="${b.brand}"><div class="business-head ${b.brand}"><span>${b.brand==="wbm"?"WBM":"ID"}</span><div><h2>${esc(b.display_name)}</h2><p>Invoice prefix ${esc(b.invoice_prefix)}</p></div></div><div class="settings-fields"><label>Trading name<input name="display_name" value="${attr(b.display_name)}" required></label><label>Legal name<input name="legal_name" value="${attr(b.legal_name)}" required></label><label>Email<input name="email" type="email" value="${attr(b.email||"")}"></label><label>Phone<input name="phone" value="${attr(b.phone||"")}"></label><label class="full">Website<input name="website" value="${attr(b.website||"")}"></label><label class="full">Address<textarea name="address" rows="2">${esc(b.address||"")}</textarea></label><div class="section-label full">BANK TRANSFER DETAILS</div><label>Account name<input name="account_name" value="${attr(bank.account_name||"")}"></label><label>Sort code<input name="sort_code" value="${attr(bank.sort_code||"")}"></label><label class="full">Account number<input name="account_number" value="${attr(bank.account_number||"")}"></label></div><footer><button class="primary" type="submit">Save ${esc(b.display_name)}</button></footer></form>`}).join("")}</div>`;$$('.business-form').forEach(f=>f.onsubmit=saveBusiness)}
async function saveBusiness(e){e.preventDefault();const f=e.currentTarget,fd=new FormData(f);const payload={display_name:fd.get("display_name"),legal_name:fd.get("legal_name"),email:nullable(fd.get("email")),phone:nullable(fd.get("phone")),website:nullable(fd.get("website")),address:nullable(fd.get("address")),bank_details:{account_name:nullable(fd.get("account_name")),sort_code:nullable(fd.get("sort_code")),account_number:nullable(fd.get("account_number"))}};try{state.businesses=await api(`/api/businesses/${f.dataset.business}`,{method:"PATCH",body:JSON.stringify(payload)});toast("Business details saved");renderSettings()}catch(err){toast(err.message,"error")}}

function showModal(title,fields,onSubmit,subtitle="Make the changes below, then save."){const content=$("#modal-content");content.innerHTML=`<div class="modal-head"><div><small>MARK'S BUSINESS STUDIO</small><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" id="close-modal">×</button></div><form id="dynamic-form"><div class="form-grid">${fields}</div><p id="form-error" class="error"></p><footer><button class="secondary" id="cancel-modal" type="button">Cancel</button><button class="primary" type="submit">Save</button></footer></form>`;$("#modal").classList.remove("hidden");$("#modal-overlay").classList.remove("hidden");$("#close-modal").onclick=$("#cancel-modal").onclick=closeModal;$("#dynamic-form").onsubmit=async e=>{e.preventDefault();$("#form-error").textContent="";try{await onSubmit(e)}catch(err){$("#form-error").textContent=err.message}};setTimeout(()=>$("#dynamic-form input, #dynamic-form select, #dynamic-form textarea")?.focus(),40)}
function closeModal(){$("#modal").classList.add("hidden");$("#modal-overlay").classList.add("hidden");$("#modal-content").innerHTML=""}
function recordFields(r={}){const c=r.client||{};return `<label class="full">Business<select id="form-brand" ${r.id?"disabled":""}><option value="wbm" ${r.brand==="wbm"?"selected":""}>Weddings By Mark</option><option value="ivory" ${r.brand==="ivory"?"selected":""}>Ivory Digital</option></select></label><label class="full">Record title<input id="form-title" value="${attr(r.title||"")}" required placeholder="Sophie & James"></label><label>First name / contact<input id="form-first" value="${attr(c.first_name||"")}" required></label><label>Last name<input id="form-last" value="${attr(c.last_name||"")}"></label><label>Partner name<input id="form-partner" value="${attr(c.partner_name||"")}"></label><label>Company name<input id="form-company" value="${attr(c.company_name||"")}"></label><label>Email address<input id="form-email" type="email" value="${attr(c.email||"")}" required></label><label>Phone number<input id="form-phone" value="${attr(c.phone||"")}"></label><label class="full">Address<textarea id="form-address" rows="2">${esc(c.address||"")}</textarea></label><label>Status<select id="form-status">${statuses.map(s=>`<option value="${s}" ${(r.status||"enquiry")===s?"selected":""}>${statusText(s)}</option>`).join("")}</select></label><label>Wedding / target date<input id="form-date" type="date" value="${attr(r.event_date||"")}"></label><label>Venue / project<input id="form-detail" value="${attr(r.venue_or_project||"")}"></label><label>Package / service<input id="form-package" value="${attr(r.package_name||"")}"></label><label>Quoted total<input id="form-total" type="number" min="0" step="0.01" value="${Number(r.quoted_total||0)}"></label><label>Deposit amount<input id="form-deposit" type="number" min="0" step="0.01" value="${Number(r.deposit_amount||0)}"></label><label>Deposit paid date<input id="form-deposit-date" type="date" value="${attr(r.deposit_paid_date||"")}"></label><label>Balance due date<input id="form-balance-date" type="date" value="${attr(r.balance_due_date||"")}"></label><label class="full">Main notes<textarea id="form-notes" rows="3">${esc(r.notes||"")}</textarea></label>`}
function recordPayload(existing=false){const brand=existing?state.current.brand:value("#form-brand");return {title:value("#form-title").trim(),status:value("#form-status"),event_date:nullable(value("#form-date")),venue_or_project:nullable(value("#form-detail")),package_name:nullable(value("#form-package")),quoted_total:Number(value("#form-total")||0),deposit_amount:Number(value("#form-deposit")||0),deposit_paid_date:nullable(value("#form-deposit-date")),balance_due_date:nullable(value("#form-balance-date")),notes:nullable(value("#form-notes")),client:{first_name:value("#form-first").trim(),last_name:value("#form-last").trim(),partner_name:nullable(value("#form-partner")),company_name:nullable(value("#form-company")),email:value("#form-email").trim(),phone:nullable(value("#form-phone")),address:nullable(value("#form-address"))},...(existing?{}:{brand,kind:brand==="wbm"?"wedding":"digital"})}}
function openRecordModal(r=null){const digital=!r&&(state.view==="projects"||state.brand==="ivory");const base=r||{brand:digital?"ivory":"wbm",status:"enquiry",client:{}};showModal(r?"Edit full record":digital?"Add a digital project":"Add a new booking",recordFields(base),async()=>{const payload=recordPayload(!!r);if(r)await api(`/api/bookings/${r.id}`,{method:"PATCH",body:JSON.stringify(payload)});else await api("/api/bookings",{method:"POST",body:JSON.stringify(payload)});closeModal();await refresh();toast(r?"Record updated":payload.kind==="wedding"?"Wedding booking created":"Digital project created");if(r)openDrawer(r.id);else navigate(payload.kind==="wedding"?"weddings":"projects")},r?"Update contact, booking, status and payment dates.":"Start with as much detail as you have. Everything stays editable.")}

async function openDrawer(id,tab="Overview"){try{const r=await api(`/api/bookings/${id}`);state.current=r;state.currentTab=tab;const drawer=$("#drawer");drawer.innerHTML=`<div class="drawer-head ${r.brand}"><div class="drawer-person"><span>${esc(initials(r))}</span><div><small>${r.kind==="wedding"?"WEDDING BOOKING":"DIGITAL PROJECT"}</small><h2>${esc(r.title)}</h2><p>${esc(r.venue_or_project||"Details not set")} · ${esc(fmtDate(r.event_date))}</p></div></div><button id="close-drawer">×</button></div><div class="tabs">${["Overview","Client portal","Notes & activity","Workflow","Documents","Finance"].map(t=>`<button class="${t===tab?"active":""}" data-tab="${t}">${t}</button>`).join("")}</div><div id="drawer-body" class="drawer-body"></div><footer><button class="secondary ${r.archived?"":"danger-button"}" id="archive-record">${r.archived?"Restore record":"Archive record"}</button><button class="primary" id="edit-record">Edit full record</button></footer>`;drawer.classList.remove("hidden");$("#drawer-overlay").classList.remove("hidden");$("#close-drawer").onclick=closeDrawer;$("#edit-record").onclick=()=>openRecordModal(r);$("#archive-record").onclick=()=>toggleArchive(r);$$('[data-tab]',drawer).forEach(b=>b.onclick=()=>{state.currentTab=b.dataset.tab;$$('[data-tab]',drawer).forEach(x=>x.classList.remove("active"));b.classList.add("active");renderTab(r,b.dataset.tab)});renderTab(r,tab)}catch(e){toast(e.message,"error")}}
function closeDrawer(){$("#drawer").classList.add("hidden");$("#drawer-overlay").classList.add("hidden");state.current=null}
function renderTab(r,tab){const body=$("#drawer-body");if(tab==="Overview")renderOverview(r,body);else if(tab==="Client portal")renderClientPortal(r,body);else if(tab==="Notes & activity")renderNotes(r,body);else if(tab==="Workflow")renderWorkflow(r,body);else if(tab==="Documents")renderRecordDocuments(r,body);else renderFinance(r,body)}
function renderOverview(r,body){body.innerHTML=`<section class="summary"><div><small>STATUS</small><strong class="status ${statusClass(r.status)}">${esc(statusText(r.status))}</strong></div><div><small>PACKAGE / SERVICE</small><strong>${esc(r.package_name||"Not selected")}</strong></div><div><small>VALUE</small><strong>${money(r.quoted_total)}</strong></div></section><section class="detail-grid"><article class="detail"><h3>Contact</h3><dl><dt>Name</dt><dd>${esc([r.client.first_name,r.client.last_name].filter(Boolean).join(" "))}</dd>${r.client.partner_name?`<dt>Partner</dt><dd>${esc(r.client.partner_name)}</dd>`:""}${r.client.company_name?`<dt>Company</dt><dd>${esc(r.client.company_name)}</dd>`:""}<dt>Email</dt><dd><a href="mailto:${attr(r.client.email)}">${esc(r.client.email)}</a></dd><dt>Phone</dt><dd>${esc(r.client.phone||"Not set")}</dd><dt>Address</dt><dd>${esc(r.client.address||"Not set")}</dd></dl></article><article class="detail"><h3>Booking / project</h3><dl><dt>Date</dt><dd>${esc(fmtDate(r.event_date))}</dd><dt>Venue / project</dt><dd>${esc(r.venue_or_project||"Not set")}</dd><dt>Deposit</dt><dd>${money(r.deposit_amount)}${r.deposit_paid_date?` · paid ${esc(fmtDate(r.deposit_paid_date))}`:""}</dd><dt>Balance due</dt><dd>${esc(fmtDate(r.balance_due_date))}</dd></dl></article></section><article class="detail"><h3>Main notes</h3><p class="preline">${esc(r.notes||"No main notes added yet.")}</p></article>`}
async function renderClientPortal(r,body){body.innerHTML=`<div class="loading">Loading client portal…</div>`;try{const d=await api(`/api/bookings/${r.id}/portal`),url=state.portalLinks[r.id]||"";body.innerHTML=`<div class="section-actions"><div><h3>Secure client portal</h3><p>Forms, final details and electronic agreement</p></div><button id="generate-link" class="primary">Generate new link</button></div>${url?`<div class="portal-link"><input id="portal-url" readonly value="${attr(url)}"><button id="copy-link" class="secondary">Copy</button></div><div class="portal-email"><select id="portal-email-template"><option value="booking_link">Booking link</option><option value="quote">Quote email</option>${r.kind==="wedding"?`<option value="final_questionnaire">Final questionnaire</option>`:""}<option value="contract_reminder">Agreement reminder</option></select><button id="send-portal-email" class="primary">Send to ${esc(r.client.email)}</button></div>`:`<div class="empty small-empty"><strong>No active link shown</strong>Generate a new private link. For security, links are only displayed when created.</div>`}<section class="portal-progress"><article><i class="${d.submissions.some(x=>x.form_type==="booking_form")?"complete":""}">${d.submissions.some(x=>x.form_type==="booking_form")?"✓":"1"}</i><span><strong>Booking form</strong><small>${d.submissions.some(x=>x.form_type==="booking_form")?`Submitted ${fmtDateTime(d.submissions.find(x=>x.form_type==="booking_form").submitted_at)}`:"Waiting"}</small></span></article>${r.kind==="wedding"?`<article><i class="${d.submissions.some(x=>x.form_type==="final_questionnaire")?"complete":""}">${d.submissions.some(x=>x.form_type==="final_questionnaire")?"✓":"2"}</i><span><strong>Final questionnaire</strong><small>${d.submissions.some(x=>x.form_type==="final_questionnaire")?"Submitted":"Waiting"}</small></span></article>`:""}<article><i class="${d.contract?"complete":""}">${d.contract?"✓":r.kind==="wedding"?"3":"2"}</i><span><strong>Agreement</strong><small>${d.contract?`Accepted by ${esc(d.contract.accepted_name)} · ${fmtDateTime(d.contract.accepted_at)}`:"Waiting"}</small></span></article></section><h3 class="section-title">Email history</h3><div class="activity-list">${d.emails.map(e=>`<div><i></i><span><strong>${esc(statusText(e.template_key))} · ${esc(e.status)}</strong><small>${esc(e.subject)} · ${fmtDateTime(e.sent_at)}</small></span></div>`).join("")||`<p class="muted" style="padding:14px">No emails sent from this record yet.</p>`}</div>`;$("#generate-link").onclick=async()=>{const x=await api(`/api/bookings/${r.id}/portal`,{method:"POST",body:JSON.stringify({expires_days:90})});state.portalLinks[r.id]=x.url;toast("Private link generated");renderClientPortal(r,body)};if(url){$("#copy-link").onclick=async()=>{await navigator.clipboard.writeText(url);toast("Private link copied")};$("#send-portal-email").onclick=async()=>{try{await api(`/api/bookings/${r.id}/emails/send`,{method:"POST",body:JSON.stringify({template_key:value("#portal-email-template"),portal_url:url})});toast("Email sent");renderClientPortal(r,body)}catch(e){toast(e.message,"error")}}}}catch(e){body.innerHTML=`<div class="empty"><strong>Unable to load client portal</strong>${esc(e.message)}</div>`}}
function renderNotes(r,body){body.innerHTML=`<form id="note-form" class="composer"><textarea id="note-body" rows="3" placeholder="Add a private note…" required></textarea><button class="primary" type="submit">Add note</button></form><section class="notes-list">${r.booking_notes.map(n=>`<article class="note-card" data-note="${n.id}"><div><time>${esc(fmtDateTime(n.created_at))}</time><button class="mini danger-text" data-action="delete-note">Delete</button></div><p>${esc(n.body)}</p></article>`).join("")||`<div class="empty small-empty"><strong>No notes yet</strong>Add the first private note above.</div>`}</section><h3 class="section-title">Activity history</h3><div class="activity-list">${r.activity.map(a=>`<div><i></i><span><strong>${esc(statusText(a.action))}</strong><small>${esc(fmtDateTime(a.created_at))}</small></span></div>`).join("")||"<p class='muted'>No activity recorded yet.</p>"}</div>`;$("#note-form").onsubmit=async e=>{e.preventDefault();await api(`/api/bookings/${r.id}/notes`,{method:"POST",body:JSON.stringify({body:value("#note-body").trim()})});toast("Note added");openDrawer(r.id,"Notes & activity")};$$('[data-action="delete-note"]',body).forEach(b=>b.onclick=async()=>{if(!confirm("Delete this note?"))return;await api(`/api/notes/${b.closest("[data-note]").dataset.note}`,{method:"DELETE"});toast("Note deleted");openDrawer(r.id,"Notes & activity")})}
function renderWorkflow(r,body){body.innerHTML=`<div class="section-actions"><div><h3>Workflow tasks</h3><p>${r.tasks.filter(t=>!t.completed).length} still open</p></div><button id="add-task" class="primary">＋ Add task</button></div><div class="task-list panel-flat">${r.tasks.map(t=>taskRow(t)).join("")||`<div class="empty small-empty"><strong>No tasks</strong>Add the first task.</div>`}</div>`;wireTaskActions(body);$("#add-task").onclick=()=>showModal("Add workflow task",`<label class="full">Task<input id="task-title" required placeholder="Send final details questionnaire"></label><label class="full">Due date and time<input id="task-due" type="datetime-local"></label>`,async()=>{await api(`/api/bookings/${r.id}/tasks`,{method:"POST",body:JSON.stringify({title:value("#task-title").trim(),due_at:nullable(value("#task-due"))})});closeModal();toast("Task added");openDrawer(r.id,"Workflow")})}
function renderRecordDocuments(r,body){body.innerHTML=`<form id="upload-form" class="upload-box"><div><strong>Upload a document</strong><small>PDF, DOCX, JPEG or PNG · maximum 25MB</small></div><select id="document-category"><option value="contract">Contract</option><option value="booking_form">Booking form</option><option value="questionnaire">Questionnaire</option><option value="quote">Quote</option><option value="attachment">Other attachment</option></select><input id="document-file" type="file" accept=".pdf,.docx,.jpg,.jpeg,.png" required><button class="primary" type="submit">Upload</button></form><div class="document-list">${r.documents.map(d=>documentRow(d)).join("")||`<div class="empty small-empty"><strong>No documents uploaded</strong>Files will stay securely attached to this record.</div>`}</div>`;$("#upload-form").onsubmit=async e=>{e.preventDefault();const file=$("#document-file").files[0];if(!file)return;const data=new FormData();data.append("file",file);await api(`/api/bookings/${r.id}/documents?category=${encodeURIComponent(value("#document-category"))}`,{method:"POST",body:data});toast("Document uploaded");openDrawer(r.id,"Documents")};wireDocumentActions(body)}
function renderFinance(r,body){const invoiced=r.invoices.reduce((s,i)=>s+i.total,0),paid=r.invoices.reduce((s,i)=>s+i.paid,0);body.innerHTML=`<section class="summary"><div><small>QUOTED</small><strong>${money(r.quoted_total)}</strong></div><div><small>INVOICED</small><strong>${money(invoiced)}</strong></div><div><small>PAID</small><strong>${money(paid)}</strong></div></section><div class="section-actions"><div><h3>Invoices & bank transfers</h3><p>Shared chronological numbering</p></div><button id="new-invoice" class="primary">＋ New invoice</button></div><div class="invoice-cards">${r.invoices.map(i=>`<article class="invoice-card"><header><div><strong>${esc(i.number)}</strong><span class="status ${statusClass(i.status)}">${esc(statusText(i.status))}</span></div><div class="file-actions"><a href="/api/invoices/${i.id}/pdf">Invoice PDF</a>${i.paid>0?`<a href="/api/invoices/${i.id}/receipt.pdf">Receipt</a>`:""}</div></header><dl><dt>Total</dt><dd>${money(i.total)}</dd><dt>Paid</dt><dd>${money(i.paid)}</dd><dt>Balance</dt><dd><strong>${money(i.balance)}</strong></dd></dl>${i.description?`<p>${esc(i.description)}</p>`:""}<div class="payments">${i.payments.map(p=>`<div data-payment="${p.id}"><span><strong>${money(p.amount)}</strong><small>${esc(fmtDate(p.paid_date))} · ${esc(statusText(p.payment_type))}</small></span><button class="mini danger-text" data-action="delete-payment">Delete</button></div>`).join("")}</div>${i.balance>0?`<button class="secondary full" data-payment-invoice="${i.id}" data-balance="${i.balance}">Record bank transfer</button>`:""}</article>`).join("")||`<div class="empty small-empty"><strong>No invoices yet</strong>Create the first branded invoice above.</div>`}</div>`;$("#new-invoice").onclick=()=>newInvoice(r);$$('[data-payment-invoice]',body).forEach(b=>b.onclick=()=>recordPayment(r,b.dataset.paymentInvoice,Number(b.dataset.balance)));$$('[data-action="delete-payment"]',body).forEach(b=>b.onclick=async()=>{if(!confirm("Remove this payment entry?"))return;await api(`/api/payments/${b.closest("[data-payment]").dataset.payment}`,{method:"DELETE"});toast("Payment removed");openDrawer(r.id,"Finance")})}
function newInvoice(r){showModal("Create branded invoice",`<label>Total<input id="invoice-total" type="number" min="0.01" step="0.01" value="${Number(r.quoted_total||0)}" required></label><label>Already paid<input id="invoice-paid" type="number" min="0" step="0.01" value="${Number(r.deposit_amount||0)}"></label><label>Issue date<input id="invoice-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Due date<input id="invoice-due" type="date" value="${attr(r.balance_due_date||"")}"></label><label class="full">Description<textarea id="invoice-description" rows="3">${esc(r.package_name||r.venue_or_project||"")}</textarea></label><label class="full">Invoice notes<textarea id="invoice-notes" rows="2" placeholder="Optional"></textarea></label>`,async()=>{const i=await api(`/api/bookings/${r.id}/invoices`,{method:"POST",body:JSON.stringify({total:Number(value("#invoice-total")),paid:Number(value("#invoice-paid")||0),issue_date:value("#invoice-date"),due_date:nullable(value("#invoice-due")),supply_date:r.event_date,description:nullable(value("#invoice-description")),notes:nullable(value("#invoice-notes"))})});closeModal();await refresh();toast(`Invoice ${i.number} created`);openDrawer(r.id,"Finance")},`The next number will use the ${r.brand==="wbm"?"WBM":"ID"} prefix and shared counter.`)}
function recordPayment(r,invoiceId,balance){showModal("Record bank transfer",`<label>Amount<input id="payment-amount" type="number" min="0.01" max="${balance}" step="0.01" value="${balance}" required></label><label>Date received<input id="payment-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label class="full">Reference<input id="payment-reference" placeholder="Bank reference or invoice number"></label><label class="full">Notes<textarea id="payment-notes" rows="2"></textarea></label>`,async()=>{await api(`/api/invoices/${invoiceId}/payments`,{method:"POST",body:JSON.stringify({amount:Number(value("#payment-amount")),paid_date:value("#payment-date"),payment_type:"bank_transfer",reference:nullable(value("#payment-reference")),notes:nullable(value("#payment-notes"))})});closeModal();await refresh();toast("Bank transfer recorded");openDrawer(r.id,"Finance")})}
async function toggleArchive(r){const action=r.archived?"restore":"archive";if(!r.archived&&!confirm("Archive this record? You can restore it from the Archived filter."))return;try{await api(`/api/bookings/${r.id}/${action}`,{method:"POST"});closeDrawer();await refresh();toast(r.archived?"Record restored":"Record archived");render()}catch(e){toast(e.message,"error")}}
function showError(e){$("#content").innerHTML=`<div class="panel empty"><strong>Something went wrong</strong>${esc(e.message)}</div>`}

init();
